<summary>Exact synthetic controller (SHA-256 2bc182d5f45cf7b751999704266aecdb7785419fcb81e3c2e29993694500d441)</summary>

Save as `/tmp/openclaw-ingress-crash-proof.mjs` and run from the built checkout above. It generates ephemeral credentials locally and retires its own Gateway process groups.

```js
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { randomBytes, createHmac } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import fs from 'node:fs/promises';
import { createServer } from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

assert.equal(process.platform, 'linux', 'This Testbox controller verifies process exit via /proc.');
const cancellation = new AbortController();
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.once(signal, () => cancellation.abort(new Error(`Proof interrupted by ${signal}`)));
}
const root = await fs.mkdtemp(path.join(os.tmpdir(), 'openclaw-ingress-crash-proof-'));
const stateDir = path.join(root, 'state');
const pluginDir = path.join(root, 'proof-plugin');
await fs.mkdir(pluginDir, { recursive: true });
await fs.mkdir(stateDir, { recursive: true });
const eventId = 'SM' + '2'.repeat(32);
const accountSid = 'AC' + '1'.repeat(32);
const authToken = randomBytes(24).toString('hex');
const queueName = JSON.stringify(['sms', 'default']);
const gatewayLog = createWriteStream(path.join(root, 'gateway-live.log'), { mode: 0o600 });
let release = false;
let attempts = 0;
const completions = [];
const blocked = new Set();
const control = createServer((req, res) => {
  if (req.url === '/enter') {
    attempts++;
    if (release) res.end('continue');
    else { blocked.add(res); res.on('close', () => blocked.delete(res)); }
  } else if (req.url === '/complete') {
    completions.push(eventId);
    res.end('recorded');
  } else { res.writeHead(404); res.end(); }
});
await new Promise(resolve => control.listen(0, '127.0.0.1', resolve));
const controlUrl = `http://127.0.0.1:${control.address().port}`;
const reserve = createServer();
await new Promise(resolve => reserve.listen(0, '127.0.0.1', resolve));
const port = reserve.address().port;
await new Promise(resolve => reserve.close(resolve));
const webhookUrl = `http://127.0.0.1:${port}/webhooks/sms`;
const signedUrl = 'https://sms-proof.example.test/webhooks/sms';
await fs.writeFile(path.join(pluginDir, 'openclaw.plugin.json'), JSON.stringify({
  id: 'ingress-proof', name: 'Synthetic ingress crash proof',
  activation: { onStartup: true },
  configSchema: { type: 'object', additionalProperties: false, properties: {} },
}));
await fs.writeFile(path.join(pluginDir, 'index.cjs'), `module.exports = {
  id: 'ingress-proof', register(api) {
    console.log('INGRESS_PROOF_GATEWAY_PID=' + process.pid);
    api.on('before_dispatch', async (event) => {
      if (event.channel !== 'sms' || event.messageId !== ${JSON.stringify(eventId)}) return;
      await fetch(${JSON.stringify(controlUrl + '/enter')});
      await fetch(${JSON.stringify(controlUrl + '/complete')});
      return { handled: true };
    });
  }
};`);
const config = {
  gateway: { mode: 'local', bind: 'loopback', auth: { mode: 'token', token: randomBytes(24).toString('hex') } },
  agents: { ownership: 'explicit', defaults: { model: { primary: 'openai/gpt-5.6-sol' } }, entries: { main: { workspace: path.join(root, 'workspace') } } },
  bindings: [{ agentId: 'main', match: { channel: 'sms', accountId: 'default' } }],
  plugins: { enabled: true, allow: ['sms', 'ingress-proof'], load: { paths: [path.join(pluginDir, 'index.cjs')] }, entries: { sms: { enabled: true }, 'ingress-proof': { enabled: true } } },
  channels: { sms: { enabled: true, accountSid, authToken, fromNumber: '+15550001111', publicWebhookUrl: signedUrl, webhookPath: '/webhooks/sms', dmPolicy: 'allowlist', allowFrom: ['+15550002222'] } },
};
const configPath = path.join(stateDir, 'openclaw.json');
await fs.writeFile(configPath, JSON.stringify(config), { mode: 0o600 });
// The child needs executable lookup, not the lease's provider credentials or operator config.
const env = {
  PATH: process.env.PATH,
  HOME: root,
  TMPDIR: os.tmpdir(),
  LANG: 'C.UTF-8',
  OPENCLAW_STATE_DIR: stateDir,
  OPENCLAW_HOME: root,
  OPENCLAW_CONFIG_PATH: configPath,
  OPENCLAW_NO_RESPAWN: '1',
  OPENCLAW_SKIP_STARTUP_MODEL_PREWARM: '1',
};
let gateway;
let gatewayPid;
let output = '';
let generation = 0;
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
async function until(predicate, label, timeout = 120000) {
  const start = Date.now();
  while (!(await predicate())) {
    cancellation.signal.throwIfAborted();
    if (Date.now() - start > timeout) throw new Error(`Timed out: ${label}\n${output.slice(-12000)}`);
    if (gateway && (gateway.exitCode !== null || gateway.signalCode !== null)) throw new Error(`Gateway exited ${gateway.exitCode ?? gateway.signalCode}: ${output.slice(-12000)}`);
    await delay(50);
  }
}
async function startGateway() {
  cancellation.signal.throwIfAborted();
  generation++;
  output = '';
  gatewayPid = undefined;
  gatewayLog.write(`\n--- Gateway generation ${generation} ---\n`);
  gateway = spawn('pnpm', ['openclaw', 'gateway', 'run', '--port', String(port), '--allow-unconfigured'], { cwd: process.cwd(), env, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
  gateway.on('error', error => { output += String(error); });
  for (const stream of [gateway.stdout, gateway.stderr]) stream.on('data', chunk => {
    output += chunk.toString();
    gatewayLog.write(chunk);
    const match = output.match(/INGRESS_PROOF_GATEWAY_PID=(\d+)/);
    if (match) gatewayPid = Number(match[1]);
  });
  await until(async () => {
    if (!gatewayPid || !output.includes('Registered SMS webhook route')) return false;
    return await fetch(`http://127.0.0.1:${port}/readyz`, { signal: AbortSignal.timeout(2000) })
      .then(async response => response.ok && (await response.json()).ready === true)
      .catch(() => false);
  }, 'Gateway readiness');
  console.log(JSON.stringify({ phase: 'ready', generation, pid: gatewayPid }));
}
function readRow() {
  const db = new DatabaseSync(path.join(stateDir, 'state', 'openclaw.sqlite'), { readOnly: true });
  try { return db.prepare('SELECT queue_name, event_id, status, attempts, claim_owner, claim_token, completed_at FROM channel_ingress_events WHERE queue_name=? AND event_id=?').get(queueName, eventId); }
  finally { db.close(); }
}
function rowEvidence() {
  const row = readRow();
  return row && { ...row, claim_token: row.claim_token ? '[present]' : null };
}
async function post(validSignature = true) {
  const form = { AccountSid: accountSid, MessageSid: eventId, From: '+15550002222', To: '+15550001111', Body: 'Synthetic ingress crash recovery proof', NumMedia: '0' };
  const signature = createHmac('sha1', authToken).update(signedUrl + Object.keys(form).sort().map(key => key + form[key]).join('')).digest('base64');
  const response = await fetch(webhookUrl, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded', 'x-twilio-signature': validSignature ? signature : 'invalid-synthetic-signature' }, body: new URLSearchParams(form), signal: AbortSignal.any([cancellation.signal, AbortSignal.timeout(30000)]) });
  if (!validSignature) {
    assert.equal(response.status, 403, await response.text());
    assert.equal(response.headers.get('x-openclaw-delivery-accepted'), null);
    assert.equal(readRow(), undefined);
    assert.equal(attempts, 0);
    console.log(JSON.stringify({ phase: 'invalid-signature-rejected', status: response.status }));
    return;
  }
  assert.equal(response.status, 200, await response.text());
  assert.equal(response.headers.get('x-openclaw-delivery-accepted'), 'durable');
  console.log(JSON.stringify({ phase: 'webhook-ack', status: response.status, durable: true }));
}
async function stopGateway(signal) {
  const child = gateway;
  const target = gatewayPid;
  if (target) {
    try { process.kill(target, signal); } catch (error) { if (error.code !== 'ESRCH') throw error; }
    console.log(JSON.stringify({ phase: 'stop-signal', generation, pid: target, signal }));
    const deadline = Date.now() + 30000;
    while (true) {
      const stat = await fs.readFile(`/proc/${target}/stat`, 'utf8').catch(() => '');
      if (!stat || stat.split(') ')[1]?.startsWith('Z ')) break;
      if (Date.now() > deadline) throw new Error(`Gateway ${target} did not stop`);
      await delay(25);
    }
  }
  child.stdout.destroy();
  child.stderr.destroy();
  // The detached process group belongs only to this controller. Retire the pnpm wrapper
  // after observing the actual Gateway exit so a restart never leaves an orphan wrapper.
  try { process.kill(-child.pid, 'SIGKILL'); } catch (error) { if (error.code !== 'ESRCH') throw error; }
  gateway = undefined;
  gatewayPid = undefined;
}

try {
  await startGateway();
  await post(false);
  await post();
  await until(() => attempts === 1, 'pre-completion barrier');
  assert.equal(readRow().status, 'claimed');
  assert.equal(Number(readRow().claim_owner.split(':')[0]), gatewayPid);
  assert.equal(readRow().completed_at, null);
  assert.equal(completions.length, 0);
  console.log(JSON.stringify({ phase: 'before-kill', row: rowEvidence(), completions: completions.length }));
  await stopGateway('SIGKILL');
  assert.equal(readRow().status, 'claimed');
  assert.equal(completions.length, 0);
  console.log(JSON.stringify({ phase: 'persisted-after-kill', row: rowEvidence(), completions: completions.length }));
  release = true;
  await startGateway();
  await until(() => completions.length === 1 && readRow()?.status === 'completed', 'recovered completion');
  assert.equal(attempts, 2);
  assert.equal(readRow().claim_owner, null);
  assert.equal(readRow().claim_token, null);
  console.log(JSON.stringify({ phase: 'recovered', row: rowEvidence(), attempts, completions: completions.length }));
  await post();
  await stopGateway('SIGTERM');
  await startGateway();
  await post();
  await stopGateway('SIGTERM');
  assert.equal(readRow().status, 'completed');
  assert.equal(completions.length, 1);
  assert.equal(attempts, 2);
  console.log(JSON.stringify({ phase: 'PASS', generations: generation, admissions: 3, attempts, completions: completions.length, stateDir }));
} finally {
  if (gateway) await stopGateway('SIGKILL');
  for (const res of blocked) res.destroy();
  control.closeAllConnections();
  await new Promise(resolve => control.close(resolve));
  await fs.writeFile(path.join(root, 'gateway-last.log'), output);
  await new Promise(resolve => gatewayLog.end(resolve));
  console.log(JSON.stringify({ proofArtifacts: root }));
}

```
